import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  const worker = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    const buf = new ArrayBuffer(8); new Uint8Array(buf)[0] = 7;
    wt.parentPort.postMessage({ tag: 'array', buf }, [buf]);
    wt.parentPort.postMessage({ tag: 'sender', len: buf.byteLength, det: buf.detached });
    const opt = new ArrayBuffer(4);
    wt.parentPort.postMessage({ tag: 'options', buf: opt }, { transfer: [opt] });
    wt.parentPort.postMessage({ tag: 'sender', len: opt.byteLength, det: opt.detached });
    const big = new ArrayBuffer(16); const view = new Uint8Array(big, 4, 4);
    wt.parentPort.postMessage({ tag: 'view', view }, [big]);
    wt.parentPort.postMessage({ tag: 'sender', len: view.length, off: view.byteOffset, det: big.detached });
    const rb = new ArrayBuffer(8, { maxByteLength: 16 });
    wt.parentPort.postMessage({ tag: 'resizable', buf: rb }, [rb]);
    wt.parentPort.postMessage({ tag: 'sender', len: rb.byteLength, res: rb.resizable, max: rb.maxByteLength });
    const kept = new ArrayBuffer(3);
    const attempt = (label, run) => { try { run(); } catch (e) { wt.parentPort.postMessage({ tag: 'error', label, name: e.name, code: e.code, message: e.message }); } };
    attempt('object list', () => wt.parentPort.postMessage(1, [{}]));
    attempt('duplicate', () => wt.parentPort.postMessage(1, [kept, kept]));
    attempt('string list', () => wt.parentPort.postMessage(1, 'x'));
    attempt('shared', () => wt.parentPort.postMessage(1, [new SharedArrayBuffer(2)]));
    wt.parentPort.postMessage({ tag: 'kept', len: kept.byteLength, det: kept.detached });
    wt.parentPort.postMessage({ tag: 'end' });
  `, { eval: true });
  const queue: any[] = [];
  worker.on('message', (m: any): void => { queue.push(m); });
  const next = async (): Promise<any> => {
    while (queue.length === 0) { await new Promise<void>((resolve: () => void): void => { setTimeout(resolve, 1); }); }
    return queue.shift();
  };
  let m: any = await next();
  while (m.tag !== 'end') {
    if (m.tag === 'array' || m.tag === 'options' || m.tag === 'view' || m.tag === 'resizable') console.log('received', m.tag);
    else if (m.tag === 'sender') console.log('sender', JSON.stringify(m));
    else if (m.tag === 'error') console.log(m.label, m.name, m.code, JSON.stringify(m.message));
    else console.log('kept', m.len, m.det);
    m = await next();
  }
  await worker.terminate();
  const late = new ArrayBuffer(4);
  worker.postMessage(1, [late]);
  console.log('after exit', late.byteLength, late.detached);
  console.log('done');
}
